import yaml

with open('registry.yaml') as f:
    reg = yaml.safe_load(f)

exps = reg.get('experiments', {})
success = {k: v for k, v in exps.items() if v.get('conclusion') == 'success'}

# Extract eval experiments with SR data for Figure 1 and 2
# Focus on experiments with pruning data

def extract_sr(exp):
    """Extract success rate from metrics, normalizing to percentage."""
    m = exp.get('metrics', {})
    sr = m.get('success_rate', m.get('overall_sr', m.get('overall_SR', None)))
    if sr is None:
        return None
    if isinstance(sr, (int, float)):
        if sr <= 1.0 and sr > 0:
            return sr * 100
        return sr
    return None

def extract_suite(exp):
    """Extract suite from spec or exp_id."""
    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    data_path = spec.get('data_path', '')
    combined = (cmd + ' ' + data_path).lower()
    if 'libero_object' in combined or 'libero-object' in combined:
        return 'Object'
    elif 'libero_goal' in combined or 'libero-goal' in combined:
        return 'Goal'
    elif 'libero_spatial' in combined or 'libero-spatial' in combined:
        return 'Spatial'
    elif 'libero_10' in combined or 'libero-10' in combined or 'long' in combined:
        return 'Long'
    return None

def extract_method_and_k(exp_id, exp):
    """Extract pruning method and keep ratio."""
    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    eid = exp_id.lower()
    combined = (cmd + ' ' + eid).lower()

    method = None
    if 'l2norm' in combined or 'l2_norm' in combined:
        method = 'l2norm'
    elif 'random' in combined or 'random_prune' in combined:
        method = 'random'
    elif 'attention' in combined or 'attn' in combined:
        method = 'attention'
    elif 'none' in cmd.lower() or 'baseline' in eid:
        method = 'baseline'

    k = None
    import re
    # Try k_ratio, keep_ratio patterns
    for pattern in [r'keep_ratio\s+([\d.]+)', r'k_ratio\s+([\d.]+)', r'k([\d]+)', r'k=([\d.]+)']:
        match = re.search(pattern, combined)
        if match:
            val = match.group(1)
            if '.' not in val:
                val = '0.' + val if len(val) <= 2 else val[:1] + '.' + val[1:]
            k = float(val)
            break
    if method == 'baseline':
        k = 1.0

    return method, k

def get_model(eid):
    eid = eid.lower()
    if 'openvla' in eid:
        return 'OpenVLA'
    elif 'pi05' in eid:
        return 'pi0.5'
    elif 'xvla' in eid:
        return 'X-VLA'
    elif 'smolvla' in eid:
        return 'SmolVLA'
    return None

# Collect eval data
eval_data = []
for eid, exp in success.items():
    model = get_model(eid)
    if model is None:
        continue
    suite = extract_suite(exp)
    if suite is None:
        continue
    sr = extract_sr(exp)
    if sr is None:
        continue
    method, k = extract_method_and_k(eid, exp)
    if method is None or k is None:
        continue
    eval_data.append({
        'exp_id': eid,
        'model': model,
        'suite': suite,
        'method': method,
        'k': k,
        'sr': sr,
    })

print(f"Total eval data points: {len(eval_data)}")
print()

# Group by model/suite for Figure 1 (k=0.9)
from collections import defaultdict
fig1_data = defaultdict(dict)
for d in eval_data:
    if d['k'] == 0.9 or abs(d['k'] - 0.9) < 0.01:
        key = (d['model'], d['suite'])
        method = d['method']
        if method not in fig1_data[key] or d['sr'] > fig1_data[key][method]:
            fig1_data[key][method] = d['sr']

print("=== Figure 1: Crossover Heatmap (k=0.9) ===")
for (model, suite), methods in sorted(fig1_data.items()):
    for method, sr in sorted(methods.items()):
        print(f"  {model:10s} {suite:8s} {method:10s} SR={sr:.1f}%")

print()

# Figure 2: π0.5 disruption curves
print("=== Figure 2: π0.5 Disruption Curve ===")
pi05_data = defaultdict(lambda: defaultdict(dict))
for d in eval_data:
    if d['model'] == 'pi0.5':
        pi05_data[d['suite']][d['method']][d['k']] = d['sr']

for suite in ['Object', 'Goal', 'Spatial', 'Long']:
    if suite in pi05_data:
        for method in ['baseline', 'random', 'l2norm']:
            if method in pi05_data[suite]:
                points = sorted(pi05_data[suite][method].items())
                pts_str = ', '.join(f"k={k}:{sr:.1f}%" for k, sr in points)
                print(f"  {suite:8s} {method:10s}: {pts_str}")

print()

# CV data
print("=== Figure 3: CV Data ===")
cv_exps = {k: v for k, v in success.items() if 'importance' in k.lower() or 'cv' in k.lower() or 'analysis' in k.lower()}
for eid, exp in cv_exps.items():
    m = exp.get('metrics', {})
    cv = m.get('importance_cv', None)
    if cv is not None:
        print(f"  {eid}: CV={cv}")
